function translateTemplates(text:string){
 let value=text;
 value=value.replace(/UNIT\s+(\d+)\s*·\s*LESSON\s+(\d+)/gi,(_,a,b)=>`الوحدة ${a} · الدرس ${b}`);
 value=value.replace(/LESSON\s+(\d+)\s+OF\s+(\d+)/gi,(_,a,b)=>`الدرس ${a} من ${b}`);
 value=value.replace(/UNIT\s+(\d+)\s+OF\s+(\d+)/gi,(_,a,b)=>`الوحدة ${a} من ${b}`);
 value=value.replace(/STAGE\s+(\d+)\s+OF\s+(\d+)/gi,(_,a,b)=>`المرحلة ${a} من ${b}`);
 value=value.replace(/DAY\s+(\d+)/gi,(_,a)=>`اليوم ${a}`);
 value=value.replace(/(\d+)\s*MIN(?:UTE)?S?/gi,(_,a)=>`${a} دقيقة`);
 value=value.replace(/(\d+)\s*SEC(?:OND)?S?/gi,(_,a)=>`${a} ثانية`);
 value=value.replace(/FRET\s+(\d+)/gi,(_,a)=>`فريت ${a}`);
 value=value.replace(/BAR\s+(\d+)/gi,(_,a)=>`مازورة ${a}`);
 value=value.replace(/STRING\s+([EADGBC])/gi,(_,a)=>`وتر ${a}`);
 value=value.replace(/([EADGBC])\s+STRING/gi,(_,a)=>`وتر ${a}`);
 value=value.replace(/^([A-G](?:♯|♭)?)\s+([A-Za-z]+): repeat the lower (.+)\.$/,(_,note,mode,jins)=>`${note} ${mode}: كرّر ${jins} في المنطقة الواطية.`);
 value=value.replace(/^Climb toward ([A-G](?:♯|♭)?); make the source identity clear before leaving\.$/,(_,note)=>`اطلع ناحية ${note}، وخلّي هوية المقام الأصلي واضحة قبل ما تسيبه.`);
 value=value.replace(/^Hold ([A-G](?:♯|♭)?) for two beats\. Keep that finger as the visual and aural guide\.$/,(_,note)=>`ثبّت ${note} نبضتين. خلّي الصباع ده مرشد للعين والودن.`);
 value=value.replace(/^Introduce ([A-G](?:♯|♭)?) then ([A-G](?:♯|♭)?); do not run the whole scale\.$/,(_,a,b)=>`دخل ${a} وبعدها ${b}؛ ما تجريش المقام كله طالع نازل.`);
 value=value.replace(/^Answer with (.+) around ([A-G](?:♯|♭)?)\.$/,(_,jins,note)=>`جاوب بـ${jins} حوالين ${note}.`);
 value=value.replace(/^Resolve to ([A-G](?:♯|♭)?) to stay, or retrace the pivot to ([A-G](?:♯|♭)?) to return\.$/,(_,a,b)=>`اقفل على ${a} لو هتكمّل في المقام الجديد، أو ارجع من نقطة التحويل لـ${b}.`);
 const labels:Record<string,string>={"LISTEN":"اسمع","REFERENCE":"مرجع","ROOT":"القرار","LOWER JINS":"الجنس السفلي","QUESTION / ANSWER":"سؤال / جواب","PROOF":"إثبات","SLOW ARRIVAL":"وصول بطيء","DIRECT ATTACK":"ضربة مباشرة","IN CONTEXT":"جوه الجملة","BLIND TEST":"اختبار من غير نظر","LOWER WORLD":"المنطقة الواطية","UPPER ANSWER":"الإجابة العالية","CONTROLLED PEAK":"قمة متحكّم فيها","HOME CADENCE":"قفلة للقرار","STATION":"محطة","SHIFT WITHOUT SOUND":"نقلة هادية","UPPER JINS":"الجنس العلوي","TWO DIRECTIONS":"اتجاهين","EIGHT-BAR FORM":"فورمة ٨ موازير","FROM":"من المصدر","PIVOT":"نقطة التحويل","CHANGE ONE TONE":"غيّر نغمة واحدة","COMPLETE DESTINATION":"ثبّت المقام الجديد","FIVE SWITCHES":"خمس تحويلات","DECLARE HOME":"أعلن القرار","DEVELOP":"طوّر","CLIMB":"اطلع","OPEN":"افتح","SWITCH":"حوّل","RETURN":"ارجع"};
 for(const [english,arabic] of Object.entries(labels))value=value.replace(new RegExp(`\\b${english.replace(/[.*+?^${}()|[\\]\\]/g,"\\$&")}\\b`,"g"),arabic);
 return value;
}

function preserveWhitespace(original:string,translated:string){
 const lead=original.match(/^\s*/)?.[0]??"",trail=original.match(/\s*$/)?.[0]??"";
 return `${lead}${translated}${trail}`;
}

// Longest phrase first, so "outside note" is never half-replaced by "note".
// Sorted once at module load: this runs for every text node on every DOM
// mutation, and Array.prototype.sort rewrites the shared array in place.
const SNIPPETS_BY_LENGTH=[...SNIPPETS].sort((a,b)=>b[0].length-a[0].length);

export function toEgyptianArabic(input:string){
 const body=input.trim();
 if(!body||/[\u0600-\u06ff]/.test(body)&&!/[A-Za-z]{3}/.test(body))return input;
 const exact=DETAIL_EXACT[body]??EXACT[body];if(exact)return preserveWhitespace(input,exact);
 if(/^(?:[A-G](?:♯|♭)?\d?|[1-8](?:↓|\*)?|[+−-]?\d+¢|[HWSPALoy-]+)(?:\s*[·/→|,+-]\s*(?:[A-G](?:♯|♭)?\d?|[1-8](?:↓|\*)?|[+−-]?\d+¢|[HWSPALoy-]+))*$/i.test(body))return input;
 let translated=translateTemplates(body);
 for(const [english,arabic] of SNIPPETS_BY_LENGTH)translated=translated.replaceAll(english,arabic);
 translated=translated.replace(/\bAND\b/g,"و").replace(/\bWITH\b/g,"مع").replace(/\bWITHOUT\b/g,"من غير").replace(/\bTHE\b/g,"").replace(/\bOF\b/g,"من").replace(/\bTO\b/g,"إلى");
 return preserveWhitespace(input,translated);
}

